pub fn generated_member_by_id(
    id: GeneratedMemberId,
) -> Option<(&'static GeneratedInterface, &'static GeneratedMember)> {
    let interface = GENERATED_INTERFACES.get((id.0 >> 16) as usize)?;
    let member = interface.members.get((id.0 & 0xffff) as usize)?;
    (member.id == id).then_some((interface, member))
}
